entries[359317] = { ["name"] = "Wen Lo, the River's Edge", ["text"] = "1.5 sec cast\nSummons and dismisses this mount.\n\"The rivers of Pandaria, like Wen Lo, are unpredictable in nature. They may remain calm, bringing water to the crops, or flood, bringing ruin. Wen Lo reminds us that we must adapt to the challenges of life.\"\nIn-Game Shop" }
entries[359318] = { ["name"] = "Soaring Spelltome", ["text"] = "1.5 sec cast\nSummons and dismisses this mount.\n\"In the forgotten depths of the Dalaran library, this oversized tome was found flapping madly around the room. Open the pages of this arcane-infused book and hitch a ride to magical adventure.\"\nAchievement:\nA Tour of Towers\nCategory:\nTimewalking" }
