entries[359326] = { ["name"] = "Grim Portent", ["text"] = "Unlimited range\nInstant\nFatescribe Roh-Kalo binds several players to runes upon the Loom of Fates.\n\nAfter 9 sec, if a bound player is touching their assigned rune, the Fatescribe inflicts 19968 Shadow damage to all players within the rune.\n\nIf a rune expires without its bound player inside, the Fatescribe inflicts 107829 Shadow damage to all players." }
entries[359333] = { ["name"] = "Empty Kettle of Stone Soup", ["text"] = "3 sec cast\nReagents:\nEmpty Kettle , Shaded Stone , Refreshing Spring Water (5)\nVendor:\nOlea Manu\nZone:\nZereth Mortis\nCost:\n25\n\nUse: Set out a Kettle of Stone Soup, ready to fill with delicious ingredients. Finish it to provide 70 servings to your raid or party!\n\nOnce complete, restores 173077 health and 138461 mana over 20 sec. Must remain seated while eating. If you spend at least 10 seconds eating you will become well fed and gain 53 in a stat for 1 hour.\n60" }
