entries[359364] = { ["name"] = "Bronzewing Vespoid", ["text"] = "1.5 sec cast\nSummons and dismisses this mount.\n\"Bronzewing vespoids are the result of attempting to synthesize a vespoid queen with no other members of a new hive. While no mortal has yet discovered how to synthesize a hive, the bronzewings are reliable mounts just as they are.\"\nProfession:\nProtoform Synthesis" }
entries[359366] = { ["name"] = "Buzz", ["text"] = "1.5 sec cast\nSummons and dismisses this mount.\n\"Buzz buzz buzz, buzz buzz! Buzz buzz buzz buzz buzz. Buzz buzz buzz, buzz buzz buzz.\"\nProfession:\nProtoform Synthesis" }
entries[359367] = { ["name"] = "Forged Spiteflyer", ["text"] = "1.5 sec cast\nSummons and dismisses this mount.\n\"There's nothing that can make you feel as alive quite like riding through the realm of Death while atop a being that hates you.\"\nProfession:\nProtoform Synthesis" }
entries[359372] = { ["name"] = "Mawdapted Raptora", ["text"] = "1.5 sec cast\nSummons and dismisses this mount.\n\"Since the Jailer's incursion, new raptora have been synthesized by Zereth Mortis that are capable of resisting the corrupting influence of the Maw.\"\nProfession:\nProtoform Synthesis" }
entries[359373] = { ["name"] = "Raptora Swooper", ["text"] = "1.5 sec cast\nSummons and dismisses this mount.\n\"The raptora swooper is one of the most vicious iterations of its kind, perfectly suited for its ecological niche. Needing no further adjustments, the ones synthesized today are identical to those created in the past.\"\nProfession:\nProtoform Synthesis" }
entries[359374] = { ["name"] = "Negation Ward", ["text"] = "30 yd range\n1.5 sec cast\nShields the target, causing Cosmic damage to attackers for 10 sec.\n(250ms cooldown)" }
entries[359375] = { ["name"] = "Negation Ward", ["text"] = "50 yd range\nInstant\nInflicts Cosmic damage." }
entries[359376] = { ["name"] = "Bronze Helicid", ["text"] = "1.5 sec cast\nSummons and dismisses this mount.\n\"Some helicids of Zereth Mortis have strangely metallic shells. The ones who do are generally a bronze color, indistinct from the metal any novice miner could work, save that this creature's construction far surpasses the skill of any novice.\"\nProfession:\nProtoform Synthesis" }
entries[359377] = { ["name"] = "Unsuccessful Prototype Fleetpod", ["text"] = "1.5 sec cast\nSummons and dismisses this mount.\n\"This creature was not designed by the First Ones, but instead by an unknown being attempting to create a very fast runner. Needless to say the attempt failed, because this mount is very slow.\"\nProfession:\nProtoform Synthesis" }
entries[359378] = { ["name"] = "Scarlet Helicid", ["text"] = "1.5 sec cast\nSummons and dismisses this mount.\n\"This helicid's unusual reddish tint is clearly intentional in its design, but the only other difference between these and other helicids is the unusual lack of any ooze.\"\nProfession:\nProtoform Synthesis" }
entries[359379] = { ["name"] = "Shimmering Aurelid", ["text"] = "1.5 sec cast\nSummons and dismisses this mount.\n\"Though it was once created to defend the Sepulcher of the First Ones, with its primary function now completed, it now obediently follows your command.\"\nAchievement:\nGlory of the Sepulcher Raider\nCategory:\nDungeons & Raids" }
entries[359380] = { ["name"] = "Depthstalker", ["text"] = "1.5 sec cast\nSummons and dismisses this mount.\n\"Poached from Zereth Mortis, a few of these jellyfish were lost when the poachers' ship sank. They found a new home in the Great Sea's depths.\"\nTrading Post" }
entries[359381] = { ["name"] = "Cryptic Aurelid", ["text"] = "1.5 sec cast\nSummons and dismisses this mount.\n\"The Cyphers of the First Ones are beyond any mortal understanding. A curious effect of the language is that, for reasons unknown, some aurelids are drawn to mortals who aspire to unlock its mystery.\"\nAchievement:\nFrom A to Zereth\nCategory:\nShadowlands" }
entries[359383] = { ["name"] = "Immediate Extermination" }
entries[359384] = { ["name"] = "Bron's Call to Action", ["text"] = "Instant\nAfter using 75 damaging or healing spells and abilities, your next spell or ability summons Bron, who knocks enemies back on arrival and then attacks and heals your targets for 30 sec." }
entries[359386] = { ["name"] = "Mawsworn Barrier" }
entries[359387] = { ["name"] = "Winds of Winter", ["text"] = "Instant\nWhile inside the Maw or Torghast, each time you deal a critical strike, the Winds accumulate 13% of that effect, up to a cap of 28572 per critical strike.\n\nEvery 20 sec, the Winds unleash, dealing Frost damage equal to the total accumulation and and surrounding you in the Winds for 20 sec, absorbing 100% of damage dealt by the Winds." }
entries[359395] = { ["name"] = "Blood Link", ["text"] = "Instant\nWhile inside the Maw or Torghast, damaging an enemy establishes a Blood Link.\n\nBlood Link pulses every 3 sec, dealing 102858 Shadow damage and healing you for 100% of damage dealt. If your Blood Link would overheal you, it instead heals a nearby ally. Limit 1." }
entries[359396] = { ["name"] = "Chaos Bane", ["text"] = "Instant\nApproximately 8 procs per minute\nWhile inside the Maw or Torghast, your spells and abilities have a chance to drain a Soul Fragment from your target, granting you 605 Primary stat for 30 sec and stacking up to 15 times.\n\nWhen you reach 15 stacks, unleash Chaos Bane, dealing 90686 Shadow damage split between nearby enemies and granting you 18137 Primary stat for 15 sec.\n(500ms cooldown)" }
entries[359397] = { ["name"] = "Howling Blizzard" }
entries[359398] = { ["name"] = "Starfall" }
entries[359399] = { ["name"] = "Starfall", ["text"] = "200 yd range\nInstant\nCalls down waves of falling stars upon enemies within 40 yds, dealing [9 * (22.4% of Spell Power)] Astral damage over 8 sec. Multiple uses of this ability may overlap. [ Aetherial Kindling : Extends the duration of active Moonfires and Sunfires by 3 sec ]" }
entries[359400] = { ["name"] = "Spiked Balls", ["text"] = "Instant\nThe Painsmith drops spiked balls that roll across the chamber floor, inflicting 400 Physical damage to players caught in their path and stunning them for 8 sec." }
entries[359401] = { ["name"] = "Genesis Crawler", ["text"] = "1.5 sec cast\nSummons and dismisses this mount.\n\"The Enlightened who have observed tarachnids believe that this variety may be some of the first beings to ever walk the land of Zereth Mortis.\"\nProfession:\nProtoform Synthesis" }
entries[359402] = { ["name"] = "Tarachnid Creeper", ["text"] = "1.5 sec cast\nSummons and dismisses this mount.\n\"These tarachnids make their home in the darkest corners of Zereth Mortis, coming out only to hunt (or, sometimes, carry a rider around).\"\nProfession:\nProtoform Synthesis" }
entries[359403] = { ["name"] = "Ineffable Skitterer", ["text"] = "1.5 sec cast\nSummons and dismisses this mount.\n\"These tarachnids move with a purpose unknown to others, answering only to a higher calling. Whatever that may be, it appears to include routine assistance to mortals who need a ride. For now.\"\nProfession:\nProtoform Synthesis" }
entries[359407] = { ["name"] = "Wastewarped Deathwalker", ["text"] = "1.5 sec cast\nSummons and dismisses this mount.\n\"Raw swirling energy bound together into a cohesive form, it will only bend to the will of those strong enough to bind it.\"\nAchievement:\nShadowlands Keystone Master: Season Three\nCategory:\nDungeons" }
entries[359408] = { ["name"] = "Divine Kiss of Ohn'ahra", ["text"] = "1.5 sec cast\nSummons and dismisses this mount." }
entries[359409] = { ["name"] = "Iskaara Trader's Ottuk", ["text"] = "1.5 sec cast\nSummons and dismisses this mount.\n\"There are no guarantees when you purchase an ottuk from Tattukiaka. At least they're cute.\"\nVendor:\nTattukiaka\nZone:\nThe Azure Span\nCost:\n1\n1" }
